import{_ as a,o as t,c as r,a3 as o}from"./chunks/framework.CJlOecQn.js";const p=JSON.parse('{"title":"Health care and insurance","description":"How residents and visitors use public health care in Qatar, from the health card and your local health centre to visitor insurance, emergencies and the residency medical exam.","frontmatter":{"title":"Health care and insurance","description":"How residents and visitors use public health care in Qatar, from the health card and your local health centre to visitor insurance, emergencies and the residency medical exam.","lastChecked":"2026-10","sourceCount":13},"headers":[],"relativePath":"guide/health.md","filePath":"guide/health.md"}'),n={name:"guide/health.md"};function s(i,e,f,l,c,h){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="health-care-and-insurance" tabindex="-1">Health care and insurance <a class="header-anchor" href="#health-care-and-insurance" aria-label="Permalink to &quot;Health care and insurance&quot;">​</a></h1><p>Two public bodies provide most government health care in Qatar. Hamad Medical Corporation (HMC) runs the hospitals and specialist care, and the Primary Health Care Corporation (PHCC) runs the local health centres, while the Ministry of Public Health (MOPH) oversees the system.<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup> Private hospitals and clinics also operate alongside them.<sup class="footnote-ref"><a href="#fn1" id="fnref1:1">[1]</a></sup></p><h2 id="health-card" tabindex="-1">Health card <a class="header-anchor" href="#health-card" aria-label="Permalink to &quot;Health card&quot;">​</a></h2><p>PHCC says citizens and residents can apply for a health card to use its health centres and HMC hospitals.<sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup> With a valid card, consultations, non-emergency treatment and prescriptions at government pharmacies are subsidised.<sup class="footnote-ref"><a href="#fn2" id="fnref2:1">[2]</a></sup></p><p>The steps below are what PHCC and HMC publish on their own pages. Call PHCC on 107 before you go, so you know the current steps and fees for your case.<sup class="footnote-ref"><a href="#fn3" id="fnref3">[3]</a></sup></p><h3 id="how-to-apply" tabindex="-1">How to apply <a class="header-anchor" href="#how-to-apply" aria-label="Permalink to &quot;How to apply&quot;">​</a></h3><ul><li><strong>Nar&#39;aakom app:</strong> PHCC&#39;s app lets you request a card for yourself or your dependents. You need a Tawtheeq (National Authentication System) account and a QID valid for at least one year.<sup class="footnote-ref"><a href="#fn4" id="fnref4">[4]</a></sup></li><li><strong>At a health centre:</strong> PHCC says to go to the centre nearest your home and fill in the forms. You will get a PHCC health file number.<sup class="footnote-ref"><a href="#fn2" id="fnref2:2">[2]</a></sup></li><li><strong>Through HMC:</strong> HMC says single residents can apply through PHCC or HMC facilities, and married residents should apply through PHCC only.<sup class="footnote-ref"><a href="#fn5" id="fnref5">[5]</a></sup></li></ul><h3 id="what-to-bring" tabindex="-1">What to bring <a class="header-anchor" href="#what-to-bring" aria-label="Permalink to &quot;What to bring&quot;">​</a></h3><ul><li><strong>Adult residents:</strong> valid QID, a 4 x 3 cm photo and a bank card for the QR 100 fee.<sup class="footnote-ref"><a href="#fn2" id="fnref2:3">[2]</a></sup></li><li><strong>Children of residents:</strong> valid QID, a 4 x 3 cm photo, the inoculation card for a first issue if the child was vaccinated in Qatar, and the QR 100 fee.<sup class="footnote-ref"><a href="#fn2" id="fnref2:4">[2]</a></sup></li><li><strong>Domestic staff:</strong> valid QID, a 4 x 3 cm photo, the sponsor&#39;s QID and a QR 50 fee.<sup class="footnote-ref"><a href="#fn2" id="fnref2:5">[2]</a></sup></li><li><strong>Everyone:</strong> a copy of a phone, water or electricity bill as proof of where you live.<sup class="footnote-ref"><a href="#fn2" id="fnref2:6">[2]</a></sup></li></ul><p>PHCC accepts card payment only, no cash, and issues health cards during morning working hours only.<sup class="footnote-ref"><a href="#fn2" id="fnref2:7">[2]</a></sup></p><h3 id="renewing-or-replacing" tabindex="-1">Renewing or replacing <a class="header-anchor" href="#renewing-or-replacing" aria-label="Permalink to &quot;Renewing or replacing&quot;">​</a></h3><p>You can renew at any PHCC health centre or HMC hospital, or online through Hukoomi.<sup class="footnote-ref"><a href="#fn2" id="fnref2:8">[2]</a></sup> PHCC lists a replacement fee for non-Qataris of QR 100 if the lost card is still valid and QR 200 if it has expired.<sup class="footnote-ref"><a href="#fn2" id="fnref2:9">[2]</a></sup></p><h2 id="your-health-centre-and-family-doctor" tabindex="-1">Your health centre and family doctor <a class="header-anchor" href="#your-health-centre-and-family-doctor" aria-label="Permalink to &quot;Your health centre and family doctor&quot;">​</a></h2><p>PHCC assigns your health centre based on your residency address, under its patient registration policy.<sup class="footnote-ref"><a href="#fn4" id="fnref4:1">[4]</a></sup> In the Nar&#39;aakom app you can ask to change your health centre or family physician, and book, reschedule or cancel some appointments.<sup class="footnote-ref"><a href="#fn4" id="fnref4:2">[4]</a></sup></p><p>Your family physician is the first step for PHCC services, and that doctor can refer you to clinics you cannot book directly.<sup class="footnote-ref"><a href="#fn4" id="fnref4:3">[4]</a></sup> Dependents under 18 with a valid QID can go on your app account, and at 18 they need their own.<sup class="footnote-ref"><a href="#fn4" id="fnref4:4">[4]</a></sup></p><h2 id="phone-lines" tabindex="-1">Phone lines <a class="header-anchor" href="#phone-lines" aria-label="Permalink to &quot;Phone lines&quot;">​</a></h2><ul><li><strong>107:</strong> PHCC&#39;s line for appointments, including urgent or same day requests.<sup class="footnote-ref"><a href="#fn4" id="fnref4:5">[4]</a></sup></li><li><strong>16060:</strong> HMC&#39;s Nesma&#39;ak Patient Contact Center, open 24 hours in several languages. Call at least 24 hours ahead to change or cancel. Missing a specialist appointment can mean cancellation and a new referral.<sup class="footnote-ref"><a href="#fn6" id="fnref6">[6]</a></sup></li><li><strong>16000:</strong> the National Healthcare Helpline, which also connects you to urgent consultation services.<sup class="footnote-ref"><a href="#fn7" id="fnref7">[7]</a></sup></li></ul><h2 id="emergencies-and-urgent-care" tabindex="-1">Emergencies and urgent care <a class="header-anchor" href="#emergencies-and-urgent-care" aria-label="Permalink to &quot;Emergencies and urgent care&quot;">​</a></h2><p>For a life-threatening emergency, call 999 or go to the nearest HMC emergency department. The <a href="./emergencies">emergencies page</a> lists them.<sup class="footnote-ref"><a href="#fn7" id="fnref7:1">[7]</a></sup></p><p>For something urgent but not life-threatening, HMC points to PHCC&#39;s Urgent Care Units, which are open 24 hours and need no appointment.<sup class="footnote-ref"><a href="#fn7" id="fnref7:2">[7]</a></sup> PHCC lists the centres that have one.<sup class="footnote-ref"><a href="#fn8" id="fnref8">[8]</a></sup></p><h2 id="health-insurance-for-visitors" tabindex="-1">Health insurance for visitors <a class="header-anchor" href="#health-insurance-for-visitors" aria-label="Permalink to &quot;Health insurance for visitors&quot;">​</a></h2><p>MOPH&#39;s mandatory health insurance scheme is written for visitors. MOPH&#39;s visitor guide says it began in February 2023, and that a visitor without suitable insurance pays the full cost of treatment.<sup class="footnote-ref"><a href="#fn1" id="fnref1:2">[1]</a></sup> The law MOPH links for the health insurance system is Law No. 22 of 2021, which regulates health care services in Qatar.<sup class="footnote-ref"><a href="#fn9" id="fnref9">[9]</a></sup></p><ul><li><strong>Visitors who need a visa before arrival:</strong> you must buy a policy first, because the visa is not granted without one.<sup class="footnote-ref"><a href="#fn10" id="fnref10">[10]</a></sup></li><li><strong>Visitors with a visa on arrival:</strong> you are exempt for the first 30 days from entry, and you must buy a policy to stay longer. MOPH advises buying one anyway to avoid the cost of care.<sup class="footnote-ref"><a href="#fn10" id="fnref10:1">[10]</a></sup></li><li><strong>Hayya Card holders:</strong> you need insurance for the rest of your card&#39;s period.<sup class="footnote-ref"><a href="#fn10" id="fnref10:2">[10]</a></sup></li><li><strong>Not covered by the rule:</strong> transit passengers and temporary entry travellers. Visitor insurance also does not apply to GCC citizens.<sup class="footnote-ref"><a href="#fn1" id="fnref1:3">[1]</a></sup></li></ul><p>MOPH gives the premium as QAR 50 per month, and the shortest policy is 30 days.<sup class="footnote-ref"><a href="#fn11" id="fnref11">[11]</a></sup> The basic policy covers emergencies and accidents up to QAR 150,000, inside Qatar only, and does not cover non-emergency treatment.<sup class="footnote-ref"><a href="#fn10" id="fnref10:3">[10]</a></sup><sup class="footnote-ref"><a href="#fn1" id="fnref1:4">[1]</a></sup> Buy it from a company registered with MOPH or from an approved international insurer.<sup class="footnote-ref"><a href="#fn10" id="fnref10:4">[10]</a></sup> For questions, call 16000 and choose extension 1.<sup class="footnote-ref"><a href="#fn10" id="fnref10:5">[10]</a></sup></p><h2 id="health-insurance-for-residents" tabindex="-1">Health insurance for residents <a class="header-anchor" href="#health-insurance-for-residents" aria-label="Permalink to &quot;Health insurance for residents&quot;">​</a></h2><p>The MOPH insurance page and FAQ describe the visitor policy only, so they do not tell you what applies to residents.<sup class="footnote-ref"><a href="#fn11" id="fnref11:1">[11]</a></sup> Ask your employer what cover you have, and check with the MOPH helpline on 16000, extension 1.<sup class="footnote-ref"><a href="#fn10" id="fnref10:6">[10]</a></sup></p><h2 id="medical-exam-for-residency" tabindex="-1">Medical exam for residency <a class="header-anchor" href="#medical-exam-for-residency" aria-label="Permalink to &quot;Medical exam for residency&quot;">​</a></h2><p>Expatriates applying to live and work in Qatar go through a medical fitness exam run by the MOPH Medical Commission.<sup class="footnote-ref"><a href="#fn12" id="fnref12">[12]</a></sup></p><ol><li>Bring your original passport and a copy of your residence visa showing a mobile number.<sup class="footnote-ref"><a href="#fn12" id="fnref12:1">[12]</a></sup></li><li>If your company is arranging this, it registers you through the MOPH website.<sup class="footnote-ref"><a href="#fn12" id="fnref12:2">[12]</a></sup></li><li>MOPH lists the fee as QAR 100.<sup class="footnote-ref"><a href="#fn12" id="fnref12:3">[12]</a></sup></li><li>Results go electronically to the Ministry of Interior&#39;s residency system.<sup class="footnote-ref"><a href="#fn12" id="fnref12:4">[12]</a></sup></li></ol><p>You can check your result on the Medical Commission page, for exams done at the Medical Commission in Mesaimeer, the Red Crescent in Mesaimeer, Karwa on Industrial Road, Al Ahli Hospital, Al Emadi Hospital and Doha Clinic Hospital. Allow up to 72 hours.<sup class="footnote-ref"><a href="#fn13" id="fnref13">[13]</a></sup> The main building in Mesaimeer opens Sunday to Thursday, 7 am to 7 pm, and the phone number is 4467 9111.<sup class="footnote-ref"><a href="#fn13" id="fnref13:1">[13]</a></sup></p><p>See also: <a href="./emergencies">Emergencies and important numbers</a>, <a href="./residence-permit-and-qid">Residence permit and QID</a>, <a href="./arriving-and-visas">Arriving and visas</a>.</p><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>Ministry of Public Health, <a href="https://www.moph.gov.qa/english/departments/ministeroffice/hfid/Documents/Visitor-Guide-to-Medical-Care-in-Qatar-English.pdf" target="_blank" rel="noreferrer">Visitor Guide to Medical Care in Qatar</a>. Last checked: 2026-10. <a href="#fnref1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:4" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn2" class="footnote-item"><p>Primary Health Care Corporation, <a href="https://www.phcc.gov.qa/patients-clients/health-card" target="_blank" rel="noreferrer">Health Card</a>. Last checked: 2026-10. <a href="#fnref2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:4" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:5" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:6" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:7" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:8" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:9" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn3" class="footnote-item"><p>Primary Health Care Corporation, <a href="https://www.phcc.gov.qa/about-us/contact-us" target="_blank" rel="noreferrer">Contact Us</a>. Last checked: 2026-10. <a href="#fnref3" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn4" class="footnote-item"><p>Primary Health Care Corporation, <a href="https://www.phcc.gov.qa/patients-clients/eservice-guestpage/register-new-health-card" target="_blank" rel="noreferrer">Register New Health Card</a>. Last checked: 2026-10. <a href="#fnref4" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref4:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref4:2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref4:3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref4:4" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref4:5" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn5" class="footnote-item"><p>Hamad Medical Corporation, <a href="https://www.hamad.qa/EN/Patient-Information/How-To-Get-A-Health-Card/Pages/default.aspx" target="_blank" rel="noreferrer">Obtaining and Renewing a Health Card</a>. Last checked: 2026-10. <a href="#fnref5" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn6" class="footnote-item"><p>Hamad Medical Corporation, <a href="https://hamad.qa/EN/news/2025/March/Pages/Easier-Than-Ever-to-Manage-Your-Specialist-Appointment.aspx" target="_blank" rel="noreferrer">It&#39;s Easier Than Ever to Manage Your Specialist Appointment at Hamad Medical Corporation</a>. Last checked: 2026-10. <a href="#fnref6" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn7" class="footnote-item"><p>Hamad Medical Corporation, <a href="https://www.hamad.qa/EN/Hospitals-and-services/Emergency-Care-Services/Pages/Emergency-and-Urgent-Care-Services.aspx" target="_blank" rel="noreferrer">Emergency and Urgent Care Services</a>. Last checked: 2026-10. <a href="#fnref7" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref7:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref7:2" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn8" class="footnote-item"><p>Primary Health Care Corporation, <a href="https://www.phcc.gov.qa/health-centers/urgent-care" target="_blank" rel="noreferrer">Urgent Care</a>. Last checked: 2026-10. <a href="#fnref8" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn9" class="footnote-item"><p>Ministry of Public Health, <a href="https://www.moph.gov.qa/english/OurServices/advancedsearch/Pages/servicesdetails.aspx?serviceId=182" target="_blank" rel="noreferrer">Registration and Renewal of Registration in the health insurance system</a>. Last checked: 2026-10. <a href="#fnref9" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn10" class="footnote-item"><p>Ministry of Public Health, <a href="https://www.moph.gov.qa/english/departments/ministeroffice/hfid/Pages/Health-Insurance-Scheme.aspx" target="_blank" rel="noreferrer">Mandatory Health Insurance Scheme</a>. Last checked: 2026-10. <a href="#fnref10" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref10:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref10:2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref10:3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref10:4" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref10:5" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref10:6" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn11" class="footnote-item"><p>Ministry of Public Health, <a href="https://www.moph.gov.qa/english/departments/ministeroffice/hfid/Pages/FAQs.aspx" target="_blank" rel="noreferrer">FAQs</a>. Last checked: 2026-10. <a href="#fnref11" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref11:1" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn12" class="footnote-item"><p>Ministry of Public Health, <a href="https://www.moph.gov.qa/english/OurServices/advancedsearch/Pages/servicesdetails.aspx?serviceId=51" target="_blank" rel="noreferrer">Medical fitness Examination for residency and employment purposes</a>. Last checked: 2026-10. <a href="#fnref12" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref12:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref12:2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref12:3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref12:4" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn13" class="footnote-item"><p>Ministry of Public Health, <a href="https://www.moph.gov.qa/english/OurServices/eservices/Pages/Medical-Commission.aspx" target="_blank" rel="noreferrer">Medical Commission (MC)</a>. Last checked: 2026-10. <a href="#fnref13" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref13:1" class="footnote-backref" aria-label="Back to text">↑</a></p></li></ol></section>',34)])])}const u=a(n,[["render",s]]);export{p as __pageData,u as default};
